"""Tabulator-backed spreadsheet macro."""
import js

from antioch.elements import Div
from antioch.macros.js_library import JSLibraryMacro

# Row operations run entirely in JS. Tabulator's row and cell components must
# never reach Python: Pyodide probes an incoming object for `next`, `get`,
# `has` and friends to decide how to wrap it, and Tabulator's components warn
# loudly on every unknown property. Doing the component work here and handing
# back only a count keeps that boundary clean.
_ROW_OPS_ID = "spreadsheet-lib-row-ops"
_ROW_OPS_NAME = "__sedStatsRowOps"
_ROW_OPS = """
window.__sedStatsRowOps = {
  deleteSelected: function (table) {
    var doomed = new Set();
    (table.getRanges() || []).forEach(function (range) {
      (range.getRows() || []).forEach(function (row) { doomed.add(row); });
    });
    doomed.forEach(function (row) { row.delete(); });
    return doomed.size;
  },
  insertBelowSelection: function (table, blank) {
    var rows = [];
    (table.getRanges() || []).forEach(function (range) {
      (range.getRows() || []).forEach(function (row) { rows.push(row); });
    });
    if (!rows.length) { table.addRow(blank); return 1; }
    var last = rows[rows.length - 1];
    table.addRow(blank, false, last);
    return 1;
  }
};
"""


def _ensure_row_ops():
    # Not `is None`: Pyodide represents JS null as a `jsnull` sentinel, which
    # is not Python None, so `is None` is always False and the script would
    # never be injected. Truthiness is correct for both null and a real node.
    if not js.document.getElementById(_ROW_OPS_ID):
        script = js.document.createElement("script")
        script.id = _ROW_OPS_ID
        script.textContent = _ROW_OPS
        js.document.head.appendChild(script)

    if not hasattr(js.window, _ROW_OPS_NAME):
        raise RuntimeError(
            "the spreadsheet row helper script did not run — "
            "check the browser console for a script error")


def _row_ops():
    """
    The row-ops shim, fetched by name.

    Not `js.window.__sedStatsRowOps`: inside a class body Python mangles any
    leading-double-underscore attribute, so that expression silently becomes
    `js.window._TabulatorSheet__sedStatsRowOps`. getattr sidesteps the rewrite.
    """
    return getattr(js.window, _ROW_OPS_NAME)


class TabulatorSheet(JSLibraryMacro):
    """
    Editable spreadsheet backed by the Tabulator JS library.

    Usage:
        sheet = TabulatorSheet(data=[{"a": 1, "b": 2}], height="400px")
        DOM.add(sheet.element)

        @when(sheet.events.data_change)
        def on_change(sender, data):
            ...
    """

    def __init__(self, data=None, columns=None, height="400px", options=None,
                 editable=True, sortable=True, **kwargs):
        """
        Args:
            data: List of row dicts
            columns: Tabulator column definitions; if None, columns are
                     auto-generated from the data (and regenerate on set_data)
            height: CSS height of the table; falsy sizes to content
            options: Extra Tabulator options merged over the defaults
            editable: Whether auto-generated columns accept typing
            sortable: Whether auto-generated columns sort on their header
        """
        super().__init__(macro_type="tabulator_sheet", **kwargs)

        self._set_state(
            data=data or [],
            columns=columns,
            height=height,
            options=options or {},
            editable=editable,
            sortable=sortable,
        )

        self._create_event('data_change')

        # Tabulator's constructor returns before the table exists: it builds
        # asynchronously and announces itself with `tableBuilt`. Anything that
        # touches the rendered table has to wait for that, so a redraw asked
        # for too early is remembered rather than thrown at a half-built table.
        self._built = False
        self._pending_redraw = False

        self._init_macro()

    def _get_library_dependencies(self):
        return {
            'scripts': ['antioch/lib/vendor/tabulator.min.js'],
            'stylesheets': ['antioch/lib/vendor/tabulator.min.css'],
        }

    def _get_library_global_name(self):
        return 'Tabulator'

    def _create_elements(self):
        container = self._register_element(
            'container', self._create_container({"width": "100%"})
        )
        holder = self._register_element('holder', Div())
        holder.set_attribute("id", f"tabulator_{self._id}")
        container.add(holder)
        return container

    def _column_definitions(self):
        columns = self._get_state('columns')
        if columns:
            return columns
        fields = []
        for row in self._get_state('data'):
            for key in row:
                if key not in fields:
                    fields.append(key)
        column = {'headerSort': self._get_state('sortable'), 'minWidth': 110}
        if self._get_state('editable'):
            column['editor'] = 'input'
            # Open with the existing value selected, so typing replaces it.
            # Editing already costs a double-click, and someone who has gone
            # to that trouble usually means to overwrite the cell rather than
            # append to it; one more click puts the caret where they want.
            column['editorParams'] = {'selectContents': True}
        return [{'title': field, 'field': field, **column} for field in fields]

    def _build_options(self):
        options = {
            'data': self._get_state('data'),
            'layout': 'fitColumns',
            'columns': self._column_definitions(),
            # A row-number gutter, as a spreadsheet has. With row selection on,
            # Tabulator's range module otherwise claims the first visible
            # column as its row header — skipping it in every range and
            # dropping it from the copy. Its own column keeps the first data
            # column being data.
            'rowHeader': {
                'formatter': 'rownum',
                'hozAlign': 'center',
                'headerSort': False,
                'resizable': False,
                'frozen': True,
                'width': 44,
            },
            'nestedFieldSeparator': False,
            'selectableRange': True,
            'selectableRangeColumns': True,
            'selectableRangeRows': True,
            'selectableRangeClearCells': self._get_state('editable'),
            'clipboard': True,
            'clipboardCopyRowRange': 'range',
            'clipboardCopyConfig': {'columnHeaders': True, 'rowHeaders': False},
            'clipboardPasteParser': 'range',
            'clipboardPasteAction': 'range',
            # Single click selects, so editing needs the second one — the
            # spreadsheet convention, and the only way both gestures fit.
            'editTriggerEvent': 'dblclick',
            'editorEmptyValue': None,
            # Tabulator warns that a sortable header and column range selection
            # fight over the same click; confining sorting to the icon is the
            # resolution it recommends.
            'headerSortClickElement': 'icon',
        }
        height = self._get_state('height')
        if height:
            options['height'] = height
        options.update(self._get_state('options'))
        return options

    def _create_js_instance(self):
        _ensure_row_ops()
        holder = self._get_element('holder')
        table = js.Tabulator.new(holder._dom_element, self._to_js(self._build_options()))
        # dataChanged passes the plain data array; Tabulator components (cell,
        # row) must never cross into Python — Pyodide's capability probes
        # trigger Tabulator's unknown-property warnings.
        table.on('dataChanged', self._create_proxy(self._handle_data_changed))
        table.on('tableBuilt', self._create_proxy(self._handle_table_built))
        return table

    def _handle_table_built(self, *args):
        self._built = True
        if self._pending_redraw:
            self._pending_redraw = False
            self.redraw()

    def _handle_data_changed(self, data):
        rows = data.to_py()
        self._set_state(data=rows)
        self._fire_event('data_change', rows)

    # ========== Public API ==========

    def get_data(self):
        """Current table contents as a list of row dicts."""
        if not self.is_initialized:
            return list(self._get_state('data'))
        return self.js_instance.getData().to_py()

    def set_data(self, data):
        """Replace table contents, regenerating auto columns from the new data."""
        self._set_state(data=data)
        if self.is_initialized:
            if not self._get_state('columns'):
                self.js_instance.setColumns(self._to_js(self._column_definitions()))
            self.js_instance.setData(self._to_js(data))
        self._fire_event('data_change', data)
        return self

    def add_row(self):
        """Insert a blank row below the selection, or at the end if none."""
        if not self.is_initialized:
            return self
        blank = {field: "" for field in self._fields()}
        _row_ops().insertBelowSelection(
            self.js_instance, self._to_js(blank))
        self._sync_after_row_change()
        return self

    def delete_selected_rows(self):
        """
        Remove every row touched by the current selection.

        Returns the number deleted, so a caller can say nothing was selected
        rather than silently doing nothing.
        """
        if not self.is_initialized:
            return 0
        removed = int(_row_ops().deleteSelected(self.js_instance))
        if removed:
            self._sync_after_row_change()
        return removed

    def _fields(self):
        """Column field names, from explicit columns or the current data."""
        columns = self._get_state('columns')
        if columns:
            return [c['field'] for c in columns if 'field' in c]
        fields = []
        for row in self._get_state('data'):
            for key in row:
                if key not in fields:
                    fields.append(key)
        return fields

    def _sync_after_row_change(self):
        """Adding or deleting a row does not fire Tabulator's dataChanged."""
        rows = self.js_instance.getData().to_py()
        self._set_state(data=rows)
        self._fire_event('data_change', rows)

    def redraw(self):
        """Recompute layout. Needed after the table becomes visible again:
        Tabulator sizes itself on render and measures zero while hidden."""
        if not self.is_initialized:
            return self
        if not self._built:
            self._pending_redraw = True
            return self
        try:
            self.js_instance.redraw(True)
        except Exception:
            # A table torn down between the request and the call has nothing
            # to redraw, and a failed relayout is never worth an error box.
            pass
        return self

    @property
    def is_ready(self):
        return self.is_initialized

scripts/spreadsheet_lib/importers.py:
"""Parsers that turn uploaded spreadsheet files into a list of row dicts."""
import csv
import io

SUPPORTED_EXTENSIONS = (".csv", ".xls", ".xlsx")


def _rows_to_dicts(rows):
    rows = [row for row in rows if any(cell not in (None, "") for cell in row)]
    if not rows:
        return []

    headers = [
        str(header) if header not in (None, "") else f"column_{i + 1}"
        for i, header in enumerate(rows[0])
    ]
    result = []
    for row in rows[1:]:
        padded = list(row) + [""] * (len(headers) - len(row))
        result.append({
            header: "" if value is None else value
            for header, value in zip(headers, padded)
        })
    return result


def parse_csv(text: str):
    return _rows_to_dicts(list(csv.reader(io.StringIO(text))))


def parse_xlsx(content: bytes):
    from openpyxl import load_workbook

    workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
    sheet = workbook.active
    return _rows_to_dicts([list(row) for row in sheet.iter_rows(values_only=True)])


def parse_xls(content: bytes):
    import xlrd

    book = xlrd.open_workbook(file_contents=content)
    sheet = book.sheet_by_index(0)
    return _rows_to_dicts([sheet.row_values(i) for i in range(sheet.nrows)])


def parse_file(filename: str, content):
    lower = filename.lower()
    if lower.endswith(".csv"):
        return parse_csv(content)
    if lower.endswith(".xlsx"):
        return parse_xlsx(content)
    if lower.endswith(".xls"):
        return parse_xls(content)
    raise ValueError(
        f"Unsupported file type: {filename} (supported: {', '.join(SUPPORTED_EXTENSIONS)})"
    )

def rows_to_csv(rows) -> str:
    """
    Turn row dicts back into CSV text.

    The inverse of `parse_csv`, for handing the grid's contents to something
    that wants a file. Column order follows the first row, with any key a later
    row introduces appended, so a ragged set of rows still round-trips.
    """
    rows = list(rows)
    if not rows:
        return ""

    headers = list(rows[0].keys())
    seen = set(headers)
    for row in rows[1:]:
        for key in row:
            if key not in seen:
                seen.add(key)
                headers.append(key)

    buffer = io.StringIO()
    # Excel and Sheets both expect CRLF, and csv defaults to it; asking for it
    # explicitly keeps the output the same wherever this runs.
    writer = csv.writer(buffer, lineterminator="\r\n")
    writer.writerow(headers)
    for row in rows:
        writer.writerow(["" if row.get(h) is None else row.get(h, "")
                         for h in headers])
    return buffer.getvalue()

scripts/ui_lib/tabs.py:
"""Tab bar whose panels stay mounted.

Antioch's own Tabs macro swaps content by clearing the container's innerHTML,
which detaches JS-backed widgets (Tabulator, Plotly) and leaves them to
re-render on reattach. Toggling `display` instead keeps every panel in the
DOM, so those widgets only ever need a redraw, never a rebuild.
"""
from antioch.elements import Button, Div
from antioch.macros.base import Macro


class TabItem:
    def __init__(self, title, content):
        self.title = title
        self.content = content
        self.button = None


class TabView(Macro):
    """
    Horizontal tabs.

        view = TabView(tabs=[TabItem("Outputs", outputs_div)])
        DOM.add(view.element)

        @when(view.events.change)
        def on_change(sender, tab, index):
            ...
    """

    def __init__(self, tabs=None, active=0, fill=False, **kwargs):
        """
        Args:
            fill: Stretch to the parent's height with the tab bar pinned and
                  the panel area taking the remaining space. Panels are then
                  responsible for their own scrolling.
        """
        self._fill = fill
        super().__init__(macro_type="tabview", **kwargs)

        self._tabs = []
        self._active_index = -1

        self._create_event('change')
        self._init_macro()

        for tab in (tabs or []):
            self.add_tab(tab)
        if self._tabs:
            self.set_active(active)

    def _create_elements(self):
        container_style = {"width": "100%"}
        content_style = {
            "border": "1px solid #dee2e6", "border-top": "none",
            "border-radius": "0 0 6px 6px", "padding": "16px",
            "background-color": "#fff",
        }
        if self._fill:
            container_style.update({
                "display": "flex", "flex-direction": "column",
                "height": "100%", "min-height": "0",
            })
            # min-height:0 lets this shrink below its content so the panel,
            # not the page, is what scrolls.
            content_style.update({
                "flex": "1", "min-height": "0", "overflow": "hidden",
                "border-radius": "0", "padding": "0",
            })

        container = self._register_element('container', self._create_container(container_style))
        self._register_element('bar', Div(style={
            "display": "flex", "flex-wrap": "wrap", "gap": "2px",
            "border-bottom": "2px solid #dee2e6", "margin-bottom": "0",
            "flex-shrink": "0",
        }))
        self._register_element('content', Div(style=content_style))
        container.add(self._get_element('bar'), self._get_element('content'))
        return container

    def _tab_button(self, tab, index):
        button = Button(tab.title, style={
            "padding": "9px 18px", "border": "none", "cursor": "pointer",
            "font-size": "14px", "background": "transparent", "color": "#495057",
            "border-bottom": "3px solid transparent", "margin-bottom": "-2px",
        })
        button.on_click(lambda e, i=index: self.set_active(i))
        return button

    def add_tab(self, tab):
        index = len(self._tabs)
        tab.button = self._tab_button(tab, index)
        self._get_element('bar').add(tab.button)

        wrapper_style = {"display": "none"}
        if self._fill:
            wrapper_style.update({"height": "100%", "min-height": "0"})
        wrapper = Div(tab.content, style=wrapper_style)
        tab.content = wrapper
        self._get_element('content').add(wrapper)

        self._tabs.append(tab)
        if len(self._tabs) == 1:
            self.set_active(0)
        return self

    def set_active(self, index):
        if not (0 <= index < len(self._tabs)) or index == self._active_index:
            return self
        self._active_index = index

        for i, tab in enumerate(self._tabs):
            active = i == index
            tab.content.style.display = "block" if active else "none"
            if tab.button:
                tab.button.style.color = "#0066cc" if active else "#495057"
                tab.button.style.font_weight = "600" if active else "400"
                tab.button.style.border_bottom = (
                    "3px solid #0066cc" if active else "3px solid transparent"
                )

        self._fire_event('change', self._tabs[index], index)
        return self

    def clear_tabs(self):
        self._get_element('bar')._dom_element.innerHTML = ""
        self._get_element('content')._dom_element.innerHTML = ""
        self._tabs = []
        self._active_index = -1
        return self

    @property
    def tabs(self):
        return list(self._tabs)

    @property
    def active_index(self):
        return self._active_index

scripts/ui_lib/ribbon.py:
"""Toolbar of tool buttons, one per action."""
from antioch.elements import Div
from antioch.event import when
from antioch.macros.base import Macro
from component_lib import ButtonInfo

class Ribbon(Macro):
    """
    Horizontal button bar. Each tool is (key, label); pressing one fires
    `select` with that key, and the pressed tool renders as active.

        ribbon = Ribbon(tools=[("mds", "MDS")])

        @when(ribbon.events.select)
        def on_select(sender, key):
            ...
    """

    def __init__(self, tools=None, **kwargs):
        super().__init__(macro_type="ribbon", **kwargs)

        self._buttons = {}
        self._active = None

        self._create_event('select')
        self._init_macro()

        for key, label in (tools or []):
            self.add_tool(key, label)

    def _create_elements(self):
        return self._register_element('container', self._create_container({
            "display": "flex", "flex-wrap": "wrap", "gap": "8px",
            "padding": "10px", "background-color": "#f8f9fa",
            "border": "1px solid #dee2e6", "border-radius": "6px",
            "margin-bottom": "16px",
        }))

    def add_tool(self, key, label):
        button = ButtonInfo(label, size="small", active=key == self._active)
        @when(button.events.click)
        def on_click(sender, *args):
            self.select(key)
        self._buttons[key] = button
        self._get_element('container').add(button)
        return self

    def select(self, key):
        """Select a tool, or pass None to clear the selection."""
        self._active = key
        for tool_key, button in self._buttons.items():
            active = tool_key == key
        if key is not None:
            self._fire_event('select', key)
        return self

    @property
    def active(self):
        return self._active

scripts/ui_lib/wizard.py:
"""Stepped options panel that generates output only when asked."""
import js

from antioch.elements import Button, Div, H3, Span
from antioch.macros.base import Macro

_CSS_ID = "ui-lib-wizard-css"

# Inline styles can't express media queries, and a 160px sidebar leaves too
# little room for the form on a phone. Below 640px the nav becomes a
# horizontal strip above the panel instead, as dzToolBox's dialogs do.
_CSS = """
@media (max-width: 640px) {
  .wizard-body { flex-direction: column !important; }
  .wizard-sidebar {
    width: 100% !important;
    display: flex;
    overflow-x: auto;
    border-right: none !important;
    border-bottom: 1px solid #e9ecef;
  }
  .wizard-sidebar button {
    width: auto !important;
    white-space: nowrap;
    border-left: none !important;
    border-bottom: 3px solid transparent;
  }
}
"""


def _ensure_css():
    # Not `is None`: Pyodide represents JS null as a `jsnull` sentinel, so
    # `is None` never matched and this re-injected the style on every call.
    if not js.document.getElementById(_CSS_ID):
        style = js.document.createElement("style")
        style.id = _CSS_ID
        style.textContent = _CSS
        js.document.head.appendChild(style)


class WizardPanel:
    def __init__(self, title, content, description=None):
        self.title = title
        self.content = content
        self.description = description
        self.nav_button = None


class Wizard(Macro):
    """
    Sidebar-stepped form. Panels stay mounted and are shown/hidden, so field
    values survive switching between steps.

    Fires `submit` when the action button is pressed; the handler is
    responsible for reading the panels' fields and doing the work.

        wizard = Wizard(panels=[WizardPanel("Options", options_div)],
                        submit_text="Create graphs")

        @when(wizard.events.submit)
        def on_submit(sender):
            ...
    """

    def __init__(self, panels=None, title=None, submit_text="Create", **kwargs):
        super().__init__(macro_type="wizard", **kwargs)

        self._panels = []
        self._active_index = 0
        self._set_state(title=title, submit_text=submit_text)

        self._create_event('submit')
        self._create_event('panel_change')

        self._init_macro()

        for panel in (panels or []):
            self.add_panel(panel)
        self._show_panel(0)

    def _create_elements(self):
        container = self._register_element('container', self._create_container({
            "border": "1px solid #ddd", "border-radius": "8px",
            "background-color": "#fff", "overflow": "hidden",
            "margin-top": "20px",
        }))

        title = self._get_state('title')
        if title:
            container.add(Div(title, style={
                "padding": "12px 16px", "font-weight": "600",
                "background-color": "#2c3e50", "color": "#fff",
            }))

        _ensure_css()

        sidebar = self._register_element('sidebar', Div(style={
            "width": "160px", "flex-shrink": "0",
            "border-right": "1px solid #e9ecef", "background-color": "#f8f9fa",
            "padding": "8px 0",
        }))
        sidebar.set_attribute("class", "wizard-sidebar")
        content = self._register_element('content', Div(style={
            "flex": "1", "padding": "16px", "min-width": "0",
        }))

        body = Div(sidebar, content, style={
            "display": "flex", "flex-wrap": "wrap", "align-items": "stretch",
        })
        body.set_attribute("class", "wizard-body")

        submit = self._register_element('submit', Button(self._get_state('submit_text'), style={
            "background-color": "#0066cc", "color": "#fff", "border": "none",
            "padding": "8px 18px", "border-radius": "4px", "cursor": "pointer",
            "font-size": "14px",
        }))
        # Element.on() makes its own proxy, so hand it the plain callable.
        submit.on_click(lambda e: self._fire_event('submit'))

        status = self._register_element('status', Span("", style={
            "margin-left": "12px", "font-size": "13px", "color": "#b00020",
        }))

        footer = Div(submit, status, style={
            "padding": "12px 16px", "border-top": "1px solid #e9ecef",
            "background-color": "#f8f9fa", "display": "flex", "align-items": "center",
        })

        container.add(body, footer)
        return container

    def _nav_button(self, panel, index):
        button = Button(panel.title, style={
            "display": "block", "width": "100%", "text-align": "left",
            "padding": "10px 16px", "border": "none", "background": "transparent",
            "cursor": "pointer", "font-size": "14px", "color": "#495057",
            "border-left": "3px solid transparent",
        })
        button.on_click(lambda e, i=index: self._show_panel(i))
        return button

    def _show_panel(self, index):
        if not (0 <= index < len(self._panels)):
            return self
        self._active_index = index

        for i, panel in enumerate(self._panels):
            active = i == index
            panel.content.style.display = "block" if active else "none"
            if panel.nav_button:
                panel.nav_button.style.background_color = "#fff" if active else "transparent"
                panel.nav_button.style.color = "#212529" if active else "#495057"
                panel.nav_button.style.border_left = (
                    "3px solid #0066cc" if active else "3px solid transparent"
                )
                panel.nav_button.style.font_weight = "600" if active else "400"

        self._fire_event('panel_change', self._panels[index])
        return self

    def add_panel(self, panel):
        index = len(self._panels)
        panel.nav_button = self._nav_button(panel, index)
        self._get_element('sidebar').add(panel.nav_button)

        wrapper = Div(style={"display": "none"})
        if panel.description:
            wrapper.add(Div(panel.description, style={
                "color": "#6c757d", "font-size": "13px", "margin-bottom": "14px",
            }))
        wrapper.add(panel.content)

        # _show_panel toggles this wrapper, so keep it as the panel's element
        panel.content = wrapper
        self._get_element('content').add(wrapper)

        self._panels.append(panel)
        return self

    def set_status(self, message, is_error=True):
        status = self._get_element('status')
        status.set_text(message)
        status.style.color = "#b00020" if is_error else "#146c2e"
        return self

    def set_busy(self, busy, busy_text="Working…"):
        submit = self._get_element('submit')
        submit._dom_element.disabled = bool(busy)
        submit.set_text(busy_text if busy else self._get_state('submit_text'))
        return self

    @property
    def panels(self):
        return list(self._panels)

