"""Form field groups used to build wizard panels."""
from antioch.elements import Div, Input, Label, Option, Select, Span


def set_select_options(select, values, empty_text="—"):
    """
    Replace a Select's options, keeping the current choice if it survives.

    Mirrors CheckboxGroup.set_options: refreshing the spreadsheet should not
    silently reset what the user picked.
    """
    previous = select.value
    select.clear()
    if not values:
        select.add(Option(empty_text, value=""))
        return select

    for value in values:
        select.add(Option(str(value), value=value))
    if previous in [str(v) for v in values]:
        select.value = previous
    return select


class CheckboxGroup:
    """
    A scrollable list of checkboxes with select-all / select-none shortcuts.

    Options can be replaced at runtime; previously checked values stay checked
    if they still exist, so refreshing the spreadsheet doesn't reset choices.
    """

    def __init__(self, options=None, all_checked=True, height="150px",
                 empty_text="Nothing to choose", on_change=None):
        self._all_checked = all_checked
        self._empty_text = empty_text
        self._boxes = {}
        # Called whenever the checked set changes, so callers can react to the
        # selection (showing options that only apply to certain choices).
        self.on_change = on_change

        self._list = Div(style={
            "max-height": height, "overflow-y": "auto",
            "border": "1px solid #ddd", "border-radius": "4px",
            "padding": "6px", "background-color": "#fff",
        })

        self._select_all = Span("select all", style={
            "cursor": "pointer", "color": "#0066cc", "font-size": "12px",
            "text-decoration": "underline",
        })
        self._select_none = Span("select none", style={
            "cursor": "pointer", "color": "#0066cc", "font-size": "12px",
            "margin-left": "12px", "text-decoration": "underline",
        })
        self._select_all.on_click(lambda e: self.set_all(True))
        self._select_none.on_click(lambda e: self.set_all(False))

        self.element = Div(
            Div(self._select_all, self._select_none, style={"margin-bottom": "4px"}),
            self._list,
        )

        self.set_options(options or [])

    def set_options(self, options):
        previous = {value: box._dom_element.checked for value, box in self._boxes.items()}
        self._boxes = {}
        self._list._dom_element.innerHTML = ""

        if not options:
            self._list.add(Span(self._empty_text, style={"color": "#888", "font-size": "13px"}))
            return

        for value in options:
            box = Input("checkbox", style={"margin-right": "8px"})
            box._dom_element.checked = previous.get(value, self._all_checked)
            box.on('change', lambda e: self._changed())
            self._boxes[value] = box
            self._list.add(Div(
                Label(box, Span(str(value)), style={
                    "display": "flex", "align-items": "center",
                    "font-size": "13px", "padding": "2px 0", "cursor": "pointer",
                }),
            ))
        self._changed()

    def _changed(self):
        if self.on_change:
            self.on_change(self.values())

    def set_all(self, checked):
        for box in self._boxes.values():
            box._dom_element.checked = checked
        # Setting .checked in code does not fire a DOM change event.
        self._changed()

    def values(self):
        return [value for value, box in self._boxes.items() if box._dom_element.checked]

    @property
    def options(self):
        return list(self._boxes.keys())


def labeled(label_text, control, hint=None):
    """A wizard form row: bold label, control, optional hint line."""
    children = [
        Label(label_text, style={
            "display": "block", "font-weight": "500",
            "margin-bottom": "4px", "font-size": "14px",
        }),
        control,
    ]
    if hint:
        children.append(Div(hint, style={
            "color": "#6c757d", "font-size": "12px", "margin-top": "3px",
        }))
    return Div(*children, style={"margin-bottom": "16px"})

scripts/dashboard/shell.py:
"""The page frame: header, top-level tabs, toolbar, and the two panels.

Everything here is chrome. The tab bar and toolbar are anchored and only the
panel bodies scroll, so the app behaves like an editor rather than a document.
"""
from antioch.dom import DOM
from antioch.elements import Button, Div, H1, Span
from antioch.event import when

from spreadsheet_lib import SpreadsheetUpload, TabulatorSheet
from ui_lib import TabItem, TabView, Toolbar

from .config import TOOL_MENU
from .drive import DrivePanel
from .example_data import generate_example_rows
from .gallery import Gallery

# A definite height: Tabulator sizes its virtual viewport from this, and a
# percentage would resolve against an auto-height parent and collapse.
TABLE_HEIGHT = "calc(100vh - 262px)"

PANEL_STYLE = {
    "display": "flex", "flex-direction": "column",
    "height": "100%", "min-height": "0",
}
SCROLL_STYLE = {
    "flex": "1", "min-height": "0", "overflow-y": "auto", "padding": "16px",
}

ROW_BUTTON_STYLE = {
    "background-color": "#34495e", "color": "#fff", "border": "none",
    "padding": "6px 14px", "cursor": "pointer", "font-size": "13px",
    "margin-right": "8px",
}
STATUS_STYLE = {"font-size": "13px", "color": "#6c757d"}


class AppShell:
    """
    Builds and mounts the page.

    Attributes:
        table    - TabulatorSheet holding the data
        upload   - SpreadsheetUpload above it
        drive    - DrivePanel beside it; empty and hidden when Google
                   sign-in is not configured
        toolbar  - Toolbar of tool menus; fill it with set_tool_menu()
        gallery  - Gallery of generated outputs
        tabs     - top-level TabView (Outputs first, then Spreadsheet)
    """

    def __init__(self, title="Sed/Stats"):
        self._style_body()

        self.table = TabulatorSheet(data=generate_example_rows(), height=TABLE_HEIGHT)
        self.upload = SpreadsheetUpload()
        self.drive = DrivePanel(get_rows=self.table.get_data)
        DOM.add(self._header(title))
        # Built empty: the tools it opens do not exist until the gallery does,
        # so main.py fills it in through set_tool_menu once they are wired.
        self.toolbar = Toolbar(
            toolbar_style={"background_color": "#34495e"},
            menu_item_style={"font_size": "14px", "padding": "10px 18px"},
        )
        # Cards only offer "Save to Drive" when there is a Drive to save to.
        self.gallery = Gallery(
            on_save=self.drive.save_bytes if self.drive.configured else None)

        self.tabs = TabView(fill=True, tabs=[
            TabItem("Outputs", self._outputs_panel()),
            TabItem("Spreadsheet", self._spreadsheet_panel()),
        ])
        DOM.add(Div(self.tabs.element, style={
            "flex": "1", "min-height": "0", "padding": "0 16px 16px",
            "display": "flex", "flex-direction": "column",
        }))

    @staticmethod
    def _style_body():
        # Viewport-height flex column with no page scroll, so the tab bar and
        # toolbar stay put and only the panels scroll.
        DOM.body.style.update({
            "margin": "0",
            "height": "100vh",
            "overflow": "hidden",
            "display": "flex",
            "flex-direction": "column",
            "font-family": "system-ui, -apple-system, sans-serif",
        })

    def _header(self, title):
        return Div(
            H1(title, style={"margin": "0", "font-size": "20px"}),
            # Right-aligned by its own margin-left:auto, and empty and hidden
            # when Google sign-in is not configured.
            self.drive.account_element,
            style={
                "flex-shrink": "0", "padding": "10px 16px",
                "background-color": "#2c3e50", "color": "#fff",
                "display": "flex", "align-items": "center", "gap": "12px",
            },
        )

    def set_tool_menu(self, tools):
        """
        Point the toolbar's menu entries at the tools they open.

        TOOL_MENU holds tool *keys*; this swaps each for a callback that opens
        that tool's wizard, leaving the nesting as written.
        """
        def resolve(node):
            if isinstance(node, dict):
                return {label: resolve(child) for label, child in node.items()}
            tool = tools[node]
            return lambda tool=tool: tool.open()

        self.toolbar.update_menu(resolve(TOOL_MENU))
        return self

    def _row_controls(self):
        """
        Add and delete rows.

        Tabulator has no built-in affordance for either, and a spreadsheet the
        user is expected to edit needs both. Deletion works on whatever the
        current selection touches — click a row number, or drag a range.
        """
        add = Button("Add row", style=ROW_BUTTON_STYLE)
        delete = Button("Delete selected rows", style=ROW_BUTTON_STYLE)
        status = Span("", style=STATUS_STYLE)

        @when(add.events.click)
        def on_add(sender, *args):
            self.table.add_row()
            status.set_text("Row added.")

        @when(delete.events.click)
        def on_delete(sender, *args):
            removed = self.table.delete_selected_rows()
            status.set_text(
                f"Deleted {removed} row{'s' if removed != 1 else ''}."
                if removed else
                "Nothing selected — click a row number, or drag across cells.")

        return Div(add, delete, status, style={
            "display": "flex", "align-items": "center", "flex-wrap": "wrap",
            "gap": "4px",
        })

    def _spreadsheet_panel(self):
        return Div(
            Div(self.upload.element, self.drive.element, style={
                "flex-shrink": "0", "padding": "10px 16px",
                "border-bottom": "1px solid #e9ecef",
                "display": "flex", "align-items": "center",
                "flex-wrap": "wrap", "gap": "8px",
            }),
            Div(self._row_controls(), style={
                "flex-shrink": "0", "padding": "10px 16px",
                "border-bottom": "1px solid #e9ecef",
            }),
            Div(self.table.element, style={
                "flex": "1", "min-height": "0", "padding": "16px",
            }),
            style=PANEL_STYLE,
        )

    def _outputs_panel(self):
        return Div(
            Div(self.toolbar.element, style={"flex-shrink": "0",
                                             "margin-bottom": "12px"}),
            # Only this scrolls.
            Div(self.gallery.element, style=SCROLL_STYLE),
            style=PANEL_STYLE,
        )

scripts/dashboard/matrices.py:
"""The Comparison matrices tool's output: every sample pair under one metric."""
import math

import numpy as np

from antioch.elements import Div, P

from .config import METRICS
from .dataset import series_for
from .tables import result_table

CAPTION_STYLE = {"font-size": "13px", "color": "#555", "margin": "0 0 6px 0"}


def build_matrix(charts, rows, sample_col, dimension, opts):
    metric = METRICS[opts["metric"]]
    _, series = series_for(rows, sample_col, dimension, metric["input"], opts)
    if len(series) < 2:
        return P("Need at least two samples with data to compare.",
                 style={"color": "#6c757d"})

    # sed_stats.metrics operates on arrays, not lists.
    series = [(name, np.array(data, dtype=float)) for name, data in series]

    names = [name for name, _ in series]
    body = []
    for name_i, data_i in series:
        cells = [name_i]
        for name_j, data_j in series:
            if name_i == name_j:
                cells.append("—")
            else:
                value = float(metric["func"](data_i, data_j))
                # r2 is undefined when a sample has no variance across bins
                cells.append("n/a" if math.isnan(value) else f"{value:.3g}")
        body.append(cells)

    return Div(
        P(f"{metric['label']} ({metric['note']})", style=CAPTION_STYLE),
        result_table(["Sample"] + names, body),
    )

scripts/dashboard/gallery.py:
"""The list of generated outputs, each downloadable and deletable."""
import asyncio

from antioch.elements import Button, Div, H3, P, Span
from antioch.event import when

from plot_lib import charts_to_zip, download_bytes, safe_filename

DOWNLOAD_STYLE = {
    "background-color": "#146c2e", "color": "#fff", "border": "none",
    "padding": "5px 12px", "border-radius": "4px", "cursor": "pointer",
    "font-size": "13px", "margin-right": "8px",
}
DELETE_STYLE = {
    "background-color": "#b00020", "color": "#fff", "border": "none",
    "padding": "5px 12px", "border-radius": "4px", "cursor": "pointer",
    "font-size": "13px",
}
SAVE_STATUS_STYLE = {
    "font-size": "13px", "color": "#b00020", "margin-left": "8px",
    "flex-basis": "100%",
}
CARD_STYLE = {
    "border": "1px solid #ddd", "border-radius": "8px",
    "padding": "14px", "margin-bottom": "16px", "background-color": "#fff",
}


class Gallery:
    """
    Holds generated outputs as cards.

    Each entry keeps its (name, chart) pairs so the charts can be re-fitted
    when they become visible again and exported on demand.
    """

    def __init__(self, empty_text="No graphs yet. Pick a tool above to make one.",
                 on_save=None):
        """
        Args:
            on_save: optional `async (filename, data, mime_type)` sink. When
                given, each card grows a "Save to Drive" button alongside the
                download; when None the button is left off entirely.
        """
        self._on_save = on_save
        self._entries = []
        self._empty = P(empty_text, style={"color": "#6c757d"})
        self._list = Div()
        self.element = Div(self._empty, self._list)

    @property
    def entries(self):
        return list(self._entries)

    def resize_all(self):
        """Charts measure themselves on render and read zero while hidden."""
        for entry in self._entries:
            for _, chart in entry["charts"]:
                chart.resize()

    def add(self, title, body, charts, tabview=None):
        entry = {"element": None, "charts": charts, "tabview": tabview}
        base_name = safe_filename(title, "graph")

        download = Button("Download SVG", style=DOWNLOAD_STYLE)
        delete = Button("Delete", style=DELETE_STYLE)
        buttons = [download]
        if not charts:
            download.style.display = "none"

        # The Drive panel's own status line lives in the Spreadsheet tab, so a
        # failure here would otherwise be invisible from the Outputs tab.
        save_status = Span("", style=SAVE_STATUS_STYLE)
        if self._on_save and charts:
            buttons.insert(1, self._save_button(entry, base_name, save_status))

        async def download_archive():
            try:
                download.set_text("Zipping…")
                data = await charts_to_zip(entry["charts"])
                download_bytes(data, f"{base_name}.zip")
            finally:
                download.set_text("Download SVG")

        @when(download.events.click)
        def on_download(sender, *args):
            named = entry["charts"]
            if len(named) == 1:
                named[0][1].download_svg(base_name)
            else:
                # One file per plot would mean a browser download storm, and
                # most browsers block all but the first anyway.
                asyncio.ensure_future(download_archive())

        @when(delete.events.click)
        def on_delete(sender, *args):
            self._remove(entry)

        header = Div(
            H3(title, style={"font-size": "16px", "margin": "0",
                             "flex": "1", "min-width": "0"}),
            Div(*buttons, delete, style={"flex-shrink": "0"}),
            save_status,
            style={
                "display": "flex", "align-items": "center", "gap": "10px",
                "flex-wrap": "wrap", "margin-bottom": "10px",
            },
        )

        entry["element"] = Div(header, body, style=CARD_STYLE)
        self._entries.append(entry)
        self._list.add(entry["element"])
        self._sync_empty()
        return entry

    def _save_button(self, entry, base_name, status):
        """A "Save to Drive" twin of the download button."""
        save = Button("Save to Drive", style=DOWNLOAD_STYLE)

        async def upload():
            try:
                save.set_text("Saving…")
                status.set_text("")
                named = entry["charts"]
                if len(named) == 1:
                    await self._on_save(f"{base_name}.svg",
                                        await named[0][1].to_svg(),
                                        "image/svg+xml")
                else:
                    await self._on_save(f"{base_name}.zip",
                                        await charts_to_zip(named),
                                        "application/zip")
            except Exception as error:
                # Without this the failure escapes into the event loop and the
                # user sees nothing but a button that went back to normal.
                status.set_text(str(error))
            finally:
                save.set_text("Save to Drive")

        @when(save.events.click)
        def on_save(sender, *args):
            asyncio.ensure_future(upload())

        return save

    def _remove(self, entry):
        for _, chart in entry["charts"]:
            try:
                chart.destroy()
            except Exception:
                # A chart that never initialized has nothing to tear down, and
                # a failure here must not strand the card on screen.
                pass
        entry["element"].remove()
        self._entries.remove(entry)
        self._sync_empty()

    def _sync_empty(self):
        self._empty.style.display = "none" if self._entries else "block"

scripts/dashboard/ternary_plot.py:
"""
The Ternary tool's output: three components of a whole, one point per grain.

The three apex dimensions are chosen in the wizard rather than taken from the
dimension checklist, because on a triangle the order matters — which component
sits at the top is part of the diagram's meaning, and a checklist cannot say.
"""
from antioch.elements import Div, P

from plot_lib import (
    categorical_color, series_symbol, ternary_layout, ternary_trace,
)
from sed_stats import ternary

from .config import TERNARY_TOTAL
from .dataset import sample_names
from .plots import make_plot
from .tables import result_table

CAPTION_STYLE = {"font-size": "13px", "color": "#555", "margin": "0 0 6px 0"}
NOTE_STYLE = {"color": "#6c757d"}

PLAIN_COLOR = "#4a5568"
CENTROID_COLOR = "#1a1a1a"


def build_ternary(charts, rows, sample_col, dimension, opts):
    """
    `dimension` is ignored — the three apexes come from the options panel.

    The tool runs with use_dimensions off, so there is one output rather than
    a tab per dimension.
    """
    apexes = [opts.get("apex_a"), opts.get("apex_b"), opts.get("apex_c")]
    if not all(apexes):
        return P("Choose all three apex dimensions.", style=NOTE_STYLE)
    if len(set(apexes)) < 3:
        return P("The three apexes must be different dimensions.",
                 style=NOTE_STYLE)

    grouped = _components_by_sample(rows, sample_col, apexes,
                                    opts.get("samples"))
    if not grouped:
        return P("No grains have a value for all three apex dimensions.",
                 style=NOTE_STYLE)

    order = {name: index
             for index, name in enumerate(sample_names(rows, sample_col))}
    closed = {sample: ternary.close(*parts, total=TERNARY_TOTAL)
              for sample, parts in grouped.items()}
    closed = {sample: data for sample, data in closed.items() if len(data)}
    if not closed:
        return P("Every grain had a zero or negative total across the three "
                 "components, so none can be placed on the triangle.",
                 style=NOTE_STYLE)

    traces = []
    for sample, data in closed.items():
        index = order.get(sample, 0)
        color, symbol = ((categorical_color(index), series_symbol(index))
                         if opts.get("color_by_sample", True)
                         else (PLAIN_COLOR, "circle"))
        traces.append(ternary_trace(
            data.a, data.b, data.c, sample,
            color=color, symbol=symbol,
            size=opts.get("point_size", 7),
            apex_names=apexes,
        ))

    if opts.get("show_centroids"):
        traces.extend(_centroid_traces(closed, apexes))

    title = f"{apexes[0]} – {apexes[1]} – {apexes[2]}"
    wrapper = Div(
        _caption(closed, apexes),
        Div(make_plot(
            charts, traces, title, apexes[1], apexes[2],
            height=560, show_legend=len(traces) > 1,
            filename=f"{'_'.join(apexes)}_ternary",
            extra_layout=ternary_layout(apexes, total=TERNARY_TOTAL),
        ).element),
    )
    if opts.get("show_centroids"):
        wrapper.add(_centroid_table(closed, apexes))
    return wrapper


def _components_by_sample(rows, sample_col, apexes, only_samples):
    """
    The three apex values per grain, grouped by sample.

    A grain missing any one component has no position on the triangle, so it
    is left out rather than treated as a zero — absent and zero mean different
    things in a composition.
    """
    grouped = {}
    for row in rows:
        sample = str(row.get(sample_col, "") or "").strip()
        if not sample:
            continue
        if only_samples is not None and sample not in only_samples:
            continue
        values = []
        for apex in apexes:
            raw = row.get(apex, "")
            if raw in ("", None):
                values = None
                break
            try:
                values.append(float(raw))
            except (TypeError, ValueError):
                values = None
                break
        if values is None:
            continue
        entry = grouped.setdefault(sample, ([], [], []))
        for slot, value in zip(entry, values):
            slot.append(value)
    return grouped


def _caption(closed, apexes):
    """State the plot's size, and anything that had to be done to the data."""
    plotted = sum(len(data) for data in closed.values())
    dropped = sum(data.dropped_total for data in closed.values())

    text = (f"{plotted:,} grains across {len(closed)} "
            f"sample{'s' if len(closed) != 1 else ''}, "
            f"{apexes[0]} at the top with {apexes[1]} and {apexes[2]} "
            f"along the base.")

    if any(data.needed_closure for data in closed.values()):
        lows = [data.closure_range[0] for data in closed.values()]
        highs = [data.closure_range[1] for data in closed.values()]
        text += (f" Raw totals ran {min(lows):.3g}–{max(highs):.3g}, so each "
                 f"grain was scaled to {TERNARY_TOTAL:g}.")
    else:
        text += f" Totals were already {TERNARY_TOTAL:g}."

    caption = Div(P(text, style=CAPTION_STYLE))
    if dropped:
        caption.add(P(f"{dropped:,} grain{'s' if dropped != 1 else ''} left out "
                      f"for a zero or negative total.", style=NOTE_STYLE))
    return caption


def _centroid_traces(closed, apexes):
    """A ringed marker per sample at its mean composition."""
    traces = []
    for sample, data in closed.items():
        a, b, c = ternary.centroid(data)
        trace = ternary_trace([a], [b], [c], f"{sample} mean",
                              color=CENTROID_COLOR, symbol="star", size=14,
                              opacity=1.0, apex_names=apexes)
        trace["marker"]["line"] = {"width": 1.4, "color": "#ffffff"}
        trace["showlegend"] = False
        traces.append(trace)
    return traces


def _centroid_table(closed, apexes):
    body = []
    for sample, data in closed.items():
        a, b, c = ternary.centroid(data)
        body.append([sample, f"{a:.1f}", f"{b:.1f}", f"{c:.1f}", f"{len(data):,}"])

    return Div(
        P("Mean composition per sample",
          style={**CAPTION_STYLE, "margin": "16px 0 6px 0"}),
        result_table(["Sample", *apexes, "n"], body),
    )

scripts/component_lib/utils.py:
"""
Utility functions for component library.

Provides helper functions for animations, styling, and common component patterns.
"""
from typing import Dict, Any


def inject_keyframes(keyframe_id: str, keyframes_dict: Dict[str, Dict[str, Any]]):
    """
    Inject CSS keyframes into the document in a Pythonic way.

    Args:
        keyframe_id: Unique ID for the style element
        keyframes_dict: Dictionary of animation definitions
            Format: {
                'animation-name': {
                    '0%': {'property': 'value', ...},
                    '100%': {'property': 'value', ...}
                }
            }

    Example:
        inject_keyframes('my-spin-animation', {
            'spin': {
                '0%': {'transform': 'rotate(0deg)'},
                '100%': {'transform': 'rotate(360deg)'}
            }
        })
    """
    from js import document

    # Check if already injected
    if document.getElementById(keyframe_id):
        return

    # Convert keyframes dict to CSS
    css_rules = []
    for animation_name, frames in keyframes_dict.items():
        frame_rules = []
        for selector, properties in frames.items():
            prop_list = [f"    {key.replace('_', '-')}: {value};" for key, value in properties.items()]
            frame_rules.append(f"  {selector} {{\n" + "\n".join(prop_list) + "\n  }")

        css_rules.append(f"@keyframes {animation_name} {{\n" + "\n".join(frame_rules) + "\n}")

    css_content = "\n\n".join(css_rules)

    # Create and inject style element
    style = document.createElement('style')
    style.id = keyframe_id
    style.textContent = css_content
    document.head.appendChild(style)

